<style>
    body {
        background-color: rgba(111, 106, 106);
        margin: 0;
        padding: 20px;
        display: flex;
        justify-content: center;
        align-items: center;
    }

    .main-part {
        background-color: rgb(197, 192, 191);
        width: 40%;
        padding: 40px 20px;
        border-radius: 40px;
        text-align: center;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 1px;
    }

    .text {
        font-size: 15px;
        font-weight: 600;
    }

    .round-contact {
        display: flex;
        align-items: center;
        background-color: rgba(54, 52, 52);
        padding: 0px 15px;
        height: 65px;
        margin-bottom: 15px;
        border-radius: 50px;
        width: 100%;
        gap: 12px;
    }

    .circle-icon {
        width: 45px;
        height: 45px;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        overflow: hidden;
    }

    .circle-icon img {
        width: 45px;
        height: 45px;
        object-fit: contain;
    }

    .text-explanation {
        flex: 1;
    }

    .text-explanation .title {
        color: #e9edef;
        font-size: 15px;
        font-weight: 600;
        margin: 0;
    }

    .text-explanation .subtitle {
        color: #8696a0;
        font-size: 10px;
        font-weight: 600;
        margin: 0;
    }

    .social-icons {
        display: inline-block;
    }

    .icon-img {
        width: 30px;
        height: auto;
    }

    .round-button {
        display: flex;
        align-items: center;
        background-color: rgb(237, 235, 235);
        padding: 0px 30px;
        height: 45px;
        margin-bottom: 15px;
        border-radius: 50px;
        box-shadow: 0 10px 18px rgba(0,0,0,0.2);
        width: 100%;
        gap: 12px;
